use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Number of times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // 1. Read the clock.
        let seconds = wall_clock::now().seconds;

        // 2. The single permitted fetch. A transport failure (timeout, error
        //    status, over-size body) comes back as a value and counts as zero
        //    characters fetched. A host outside the allowlist traps at the
        //    boundary, which is the intended behaviour.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // 3. Notify. The contract requires `notified == true` on every report
        //    this node produces. A report saying `true` when the channel refused
        //    the message would be false, so the node retries a few times. If the
        //    channel still refuses, the node aborts and emits no report.
        let message = format!(
            "heartbeat: t={} feed={} fetched={} chars",
            seconds, feed_url, fetched
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        if !notified {
            panic!("heartbeat: notifier refused the message");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
